IF NOT EXISTS(SELECT 1 FROM sys.indexes i WHERE i.object_id=OBJECT_ID(N''dbo.product_barcodes'') AND i.name=N''IX_WorkCatalog_ProductBarcodes_ProductActive'' AND i.type=2 AND i.is_unique=0 AND i.is_primary_key=0 AND i.is_unique_constraint=0 AND i.is_disabled=0 AND i.is_hypothetical=0 AND i.has_filter=0 AND i.filter_definition IS NULL AND CONVERT(varbinary(max),(SELECT c.name name,x.key_ordinal keyOrdinal,x.is_descending_key descending,x.is_included_column included FROM sys.index_columns x JOIN sys.columns c ON c.object_id=x.object_id AND c.column_id=x.column_id WHERE x.object_id=i.object_id AND x.index_id=i.index_id AND(x.key_ordinal>0 OR x.is_included_column=1) ORDER BY x.index_column_id FOR JSON PATH))=CONVERT(varbinary(max),N''[{"name":"product_id","keyOrdinal":1,"descending":false,"included":false},{"name":"is_active","keyOrdinal":2,"descending":false,"included":false},{"name":"barcode","keyOrdinal":0,"descending":false,"included":true},{"name":"is_primary","keyOrdinal":0,"descending":false,"included":true}]'')) THROW 51102,''WORK_CATALOG_INDEX_DRIFT'',1;
IF NOT EXISTS(SELECT 1 FROM sys.indexes i WHERE i.object_id=OBJECT_ID(N''dbo.product_source_aliases'') AND i.name=N''IX_WorkCatalog_ProductAliases_ProductSource'' AND i.type=2 AND i.is_unique=0 AND i.is_primary_key=0 AND i.is_unique_constraint=0 AND i.is_disabled=0 AND i.is_hypothetical=0 AND i.has_filter=0 AND i.filter_definition IS NULL AND CONVERT(varbinary(max),(SELECT c.name name,x.key_ordinal keyOrdinal,x.is_descending_key descending,x.is_included_column included FROM sys.index_columns x JOIN sys.columns c ON c.object_id=x.object_id AND c.column_id=x.column_id WHERE x.object_id=i.object_id AND x.index_id=i.index_id AND(x.key_ordinal>0 OR x.is_included_column=1) ORDER BY x.index_column_id FOR JSON PATH))=CONVERT(varbinary(max),N''[{"name":"product_id","keyOrdinal":1,"descending":false,"included":false},{"name":"source_product_id","keyOrdinal":2,"descending":false,"included":false}]'')) THROW 51102,''WORK_CATALOG_INDEX_DRIFT'',1;
IF NOT EXISTS(SELECT 1 FROM sys.indexes i WHERE i.object_id=OBJECT_ID(N''dbo.product_source_aliases'') AND i.name=N''IX_WorkCatalog_ProductAliases_SourceProduct'' AND i.type=2 AND i.is_unique=0 AND i.is_primary_key=0 AND i.is_unique_constraint=0 AND i.is_disabled=0 AND i.is_hypothetical=0 AND i.has_filter=0 AND i.filter_definition IS NULL AND CONVERT(varbinary(max),(SELECT c.name name,x.key_ordinal keyOrdinal,x.is_descending_key descending,x.is_included_column included FROM sys.index_columns x JOIN sys.columns c ON c.object_id=x.object_id AND c.column_id=x.column_id WHERE x.object_id=i.object_id AND x.index_id=i.index_id AND(x.key_ordinal>0 OR x.is_included_column=1) ORDER BY x.index_column_id FOR JSON PATH))=CONVERT(varbinary(max),N''[{"name":"source_product_id","keyOrdinal":1,"descending":false,"included":false},{"name":"product_id","keyOrdinal":2,"descending":false,"included":false}]'')) THROW 51102,''WORK_CATALOG_INDEX_DRIFT'',1;
 IF @@TRANCOUNT=0 OR NOT EXISTS(SELECT 1 FROM sys.dm_exec_sessions WHERE session_id=@@SPID AND transaction_isolation_level=4) THROW 51101,''STOCK_PRODUCT_READ_TRANSACTION_REQUIRED'',1;
 IF @actor_id IS NULL OR NOT EXISTS(SELECT 1 FROM dbo.users u JOIN dbo.permissions p ON p.role_id=u.role_id WHERE u.id=@actor_id AND u.is_active=1 AND p.permission_key=N''product.view'' AND p.can_view=1) THROW 51101,''STOCK_PRODUCT_READ_FORBIDDEN'',1;
 IF @page IS NULL OR @page<1 OR @page>1000000 OR @page_size IS NULL OR @page_size<1 OR @page_size>50 OR @search IS NULL OR @barcode IS NULL OR @stock IS NULL OR @stock NOT IN(N''all'',N''positive'',N''zero'',N''negative'') OR @status IS NULL OR @status NOT IN(N''all'',N''active'',N''passive'') OR(@product_id IS NOT NULL AND @product_id<1) THROW 51101,''STOCK_PRODUCT_QUERY_INVALID'',1;


 DECLARE @financial bit=0,@sales bit=CASE WHEN EXISTS(SELECT 1 FROM dbo.users u JOIN dbo.permissions p ON p.role_id=u.role_id WHERE u.id=@actor_id AND u.is_active=1 AND p.permission_key=N''sales.view'' AND p.can_view=1) THEN 1 ELSE 0 END,@read_at varchar(24)=CONVERT(varchar(23),CAST(SYSUTCDATETIME() AS datetime2(3)),126)+N''Z'';
 CREATE TABLE #StockScope(id bigint NOT NULL PRIMARY KEY,kind nvarchar(30) NOT NULL);
 INSERT #StockScope SELECT b.product_id,N''accepted-opening'' FROM erp_migration.accepted_price_products b;

 INSERT #StockScope SELECT h.native_id,N''quarantined-source'' FROM erp_migration.operation_quarantine_holds h WHERE h.entity=N''product'' AND h.native_id IS NOT NULL;
 IF @brand IS NULL OR @product_type IS NULL OR @image IS NULL OR @image NOT IN(N''all'',N''available'',N''missing'') OR @sort IS NULL OR @sort NOT IN(N''code-asc'',N''code-desc'',N''stock-desc'') OR @media_bindings IS NULL OR @candidate_bindings IS NULL OR @classification_validation IS NULL THROW 51102,''WORK_CATALOG_QUERY_INVALID'',1;

CREATE TABLE #CatalogClassification(id bigint NOT NULL PRIMARY KEY,brand nvarchar(250) NULL,product_type nvarchar(250) NULL,source_name nvarchar(500) NULL,verified bit NOT NULL,display_code nvarchar(250) NOT NULL,numeric_group int NULL,digit_length int NULL,numeric_value nvarchar(250) NULL,digit_suffix nvarchar(250) NULL,photo_available bit NOT NULL DEFAULT(0),rank bigint NULL);
IF @classification_validation=1 BEGIN
IF EXISTS(SELECT 1 FROM #StockScope s JOIN erp_migration.accepted_price_products b ON b.product_id=s.id
 LEFT JOIN dbo.products p ON p.id=s.id LEFT JOIN erp_migration.records r ON r.run_id=N''VEGA-OPENING-TEST-20261004-06'' AND r.entity=N''products'' AND r.source_key=b.product_source_key
 OUTER APPLY OPENJSON(r.payload_json) WITH(brand nvarchar(250) ''$.brand'',product_type nvarchar(250) ''$.category'',source_name nvarchar(500) ''$.name'') c
 WHERE s.kind=N''accepted-opening'' AND(p.id IS NULL OR r.source_key IS NULL OR r.payload_hash IS NULL OR r.payload_json IS NULL OR r.payload_hash<>b.stage_payload_hash OR CONVERT(char(64),HASHBYTES(''SHA2_256'',r.payload_json),2)<>b.stage_sql_hash
 OR EXISTS(SELECT CONVERT(varbinary(max),p.stock_code),CONVERT(varbinary(max),p.name),CONVERT(varbinary(max),p.source_record_key),CONVERT(varbinary(max),p.brand),CONVERT(varbinary(max),p.category) EXCEPT SELECT CONVERT(varbinary(max),b.stock_code),CONVERT(varbinary(max),b.product_name),CONVERT(varbinary(max),b.native_source_key),CONVERT(varbinary(max),c.brand),CONVERT(varbinary(max),c.product_type)))) THROW 51102,''WORK_CATALOG_BINDING_DRIFT'',1;
INSERT #CatalogClassification(id,brand,product_type,source_name,verified,display_code)
 SELECT s.id,CASE WHEN s.kind=N''accepted-opening'' THEN CASE WHEN DATALENGTH(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(c.brand,NCHAR(9),N''''),NCHAR(10),N''''),NCHAR(11),N''''),NCHAR(12),N''''),NCHAR(13),N''''),NCHAR(32),N''''),NCHAR(160),N''''),NCHAR(5760),N''''),NCHAR(8192),N''''),NCHAR(8193),N''''),NCHAR(8194),N''''),NCHAR(8195),N''''),NCHAR(8196),N''''),NCHAR(8197),N''''),NCHAR(8198),N''''),NCHAR(8199),N''''),NCHAR(8200),N''''),NCHAR(8201),N''''),NCHAR(8202),N''''),NCHAR(8232),N''''),NCHAR(8233),N''''),NCHAR(8239),N''''),NCHAR(8287),N''''),NCHAR(12288),N''''),NCHAR(65279),N''''))=0 THEN NULL ELSE c.brand END END,CASE WHEN s.kind=N''accepted-opening'' THEN CASE WHEN DATALENGTH(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(c.product_type,NCHAR(9),N''''),NCHAR(10),N''''),NCHAR(11),N''''),NCHAR(12),N''''),NCHAR(13),N''''),NCHAR(32),N''''),NCHAR(160),N''''),NCHAR(5760),N''''),NCHAR(8192),N''''),NCHAR(8193),N''''),NCHAR(8194),N''''),NCHAR(8195),N''''),NCHAR(8196),N''''),NCHAR(8197),N''''),NCHAR(8198),N''''),NCHAR(8199),N''''),NCHAR(8200),N''''),NCHAR(8201),N''''),NCHAR(8202),N''''),NCHAR(8232),N''''),NCHAR(8233),N''''),NCHAR(8239),N''''),NCHAR(8287),N''''),NCHAR(12288),N''''),NCHAR(65279),N''''))=0 THEN NULL ELSE c.product_type END END,CASE WHEN s.kind=N''accepted-opening'' THEN CASE WHEN DATALENGTH(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(c.source_name,NCHAR(9),N''''),NCHAR(10),N''''),NCHAR(11),N''''),NCHAR(12),N''''),NCHAR(13),N''''),NCHAR(32),N''''),NCHAR(160),N''''),NCHAR(5760),N''''),NCHAR(8192),N''''),NCHAR(8193),N''''),NCHAR(8194),N''''),NCHAR(8195),N''''),NCHAR(8196),N''''),NCHAR(8197),N''''),NCHAR(8198),N''''),NCHAR(8199),N''''),NCHAR(8200),N''''),NCHAR(8201),N''''),NCHAR(8202),N''''),NCHAR(8232),N''''),NCHAR(8233),N''''),NCHAR(8239),N''''),NCHAR(8287),N''''),NCHAR(12288),N''''),NCHAR(65279),N''''))=0 THEN NULL ELSE c.source_name END END,CONVERT(bit,CASE WHEN s.kind=N''accepted-opening'' THEN 1 ELSE 0 END),p.stock_code
 FROM #StockScope s JOIN dbo.products p ON p.id=s.id LEFT JOIN erp_migration.accepted_price_products b ON b.product_id=s.id LEFT JOIN erp_migration.records r ON r.run_id=N''VEGA-OPENING-TEST-20261004-06'' AND r.entity=N''products'' AND r.source_key=b.product_source_key
 OUTER APPLY OPENJSON(r.payload_json) WITH(brand nvarchar(250) ''$.brand'',product_type nvarchar(250) ''$.category'',source_name nvarchar(500) ''$.name'') c;

END ELSE BEGIN
 IF ISJSON(@candidate_bindings)<>1 OR LEFT(@candidate_bindings,1)<>N''['' OR(SELECT COUNT(*) FROM OPENJSON(@candidate_bindings))>16676 THROW 51102,''WORK_CATALOG_CANDIDATES_INVALID'',1;
 CREATE TABLE #CatalogCandidates(id bigint NOT NULL,rank bigint NOT NULL CHECK(rank BETWEEN 1 AND 16676));
 INSERT #CatalogCandidates SELECT id,rank FROM OPENJSON(@candidate_bindings) WITH(id bigint ''$[0]'',rank bigint ''$[1]'');
 CREATE UNIQUE CLUSTERED INDEX IX_CatalogCandidates_Id ON #CatalogCandidates(id);
 CREATE UNIQUE NONCLUSTERED INDEX IX_CatalogCandidates_Rank ON #CatalogCandidates(rank);
 IF EXISTS(SELECT id FROM #CatalogCandidates EXCEPT SELECT id FROM #StockScope) THROW 51102,''WORK_CATALOG_BINDING_DRIFT'',1;
 INSERT #CatalogClassification(id,verified,display_code,rank) SELECT s.id,CONVERT(bit,CASE WHEN s.kind=N''accepted-opening'' THEN 1 ELSE 0 END),p.stock_code,x.rank FROM #CatalogCandidates x JOIN #StockScope s ON s.id=x.id JOIN dbo.products p ON p.id=s.id;
END;
CREATE TABLE #CatalogMediaBindings(product_id bigint NOT NULL PRIMARY KEY,stock_code nvarchar(250) NOT NULL,source_key nvarchar(400) NOT NULL,run_id nvarchar(80) NOT NULL);
IF @image<>N''all'' BEGIN
 IF ISJSON(@media_bindings)<>1 OR LEFT(@media_bindings,1)<>N''['' OR(SELECT COUNT(*) FROM OPENJSON(@media_bindings))>3830 THROW 51102,''WORK_CATALOG_MEDIA_BINDING_INVALID'',1;
 INSERT #CatalogMediaBindings SELECT product_id,stock_code,source_key,run_id FROM OPENJSON(@media_bindings) WITH(product_id bigint ''$.productId'',stock_code nvarchar(250) ''$.stockCode'',source_key nvarchar(400) ''$.sourceKey'',run_id nvarchar(80) ''$.runId'');
 CREATE TABLE #CatalogMediaAliasTargetSources(source_product_id int NOT NULL PRIMARY KEY);
 INSERT #CatalogMediaAliasTargetSources SELECT DISTINCT TRY_CONVERT(int,b.source_id) FROM #CatalogMediaBindings m JOIN erp_migration.accepted_price_products b ON b.product_id=m.product_id WHERE TRY_CONVERT(int,b.source_id) IS NOT NULL;
 CREATE TABLE #CatalogMediaAliasPairs(product_id bigint NULL,source_product_id int NULL,pair_count bigint NOT NULL);
INSERT #CatalogMediaAliasPairs SELECT product_id,source_product_id,COUNT_BIG(*) FROM dbo.product_source_aliases a WHERE EXISTS(SELECT 1 FROM #CatalogMediaBindings m WHERE m.product_id=a.product_id) OR EXISTS(SELECT 1 FROM #CatalogMediaAliasTargetSources t WHERE t.source_product_id=a.source_product_id) GROUP BY product_id,source_product_id;
CREATE UNIQUE CLUSTERED INDEX IX_CatalogMediaAliasPairs ON #CatalogMediaAliasPairs(product_id,source_product_id);
CREATE TABLE #CatalogMediaAliasProductCounts(product_id bigint NULL,alias_count bigint NOT NULL);
INSERT #CatalogMediaAliasProductCounts SELECT product_id,SUM(pair_count) FROM #CatalogMediaAliasPairs GROUP BY product_id;
CREATE UNIQUE CLUSTERED INDEX IX_CatalogMediaAliasProductCounts ON #CatalogMediaAliasProductCounts(product_id);
CREATE TABLE #CatalogMediaAliasSourceCounts(source_product_id int NULL,alias_count bigint NOT NULL);
INSERT #CatalogMediaAliasSourceCounts SELECT source_product_id,SUM(pair_count) FROM #CatalogMediaAliasPairs GROUP BY source_product_id;
CREATE UNIQUE CLUSTERED INDEX IX_CatalogMediaAliasSourceCounts ON #CatalogMediaAliasSourceCounts(source_product_id);
 UPDATE c SET photo_available=1 FROM #CatalogClassification c JOIN #CatalogMediaBindings m ON m.product_id=c.id JOIN erp_migration.accepted_price_products b ON b.product_id=c.id JOIN dbo.products p ON p.id=c.id
 JOIN #CatalogMediaAliasProductCounts pc ON pc.product_id=c.id JOIN #CatalogMediaAliasSourceCounts sc ON sc.source_product_id=TRY_CONVERT(int,b.source_id) JOIN #CatalogMediaAliasPairs ap ON ap.product_id=c.id AND ap.source_product_id=TRY_CONVERT(int,b.source_id)
 WHERE c.verified=1 AND CONVERT(varbinary(max),m.stock_code)=CONVERT(varbinary(max),p.stock_code) AND CONVERT(varbinary(max),m.stock_code)=CONVERT(varbinary(max),b.stock_code) AND CONVERT(varbinary(max),m.source_key)=CONVERT(varbinary(max),b.product_source_key) AND CONVERT(varbinary(max),m.run_id)=CONVERT(varbinary(max),N''VEGA-OPENING-TEST-20261004-06'')
 AND NOT EXISTS(SELECT 1 FROM erp_migration.operation_quarantine_holds h WHERE h.entity=N''product'' AND(h.native_id=c.id OR h.source_id=b.source_id))
 AND pc.alias_count=1 AND sc.alias_count=1 AND ap.pair_count=1;
END;

 CREATE TABLE #StockMatches(id bigint NOT NULL PRIMARY KEY,kind nvarchar(30) NOT NULL);
 INSERT #StockMatches SELECT s.id,s.kind FROM #StockScope s JOIN dbo.products p ON p.id=s.id JOIN #CatalogClassification c ON c.id=s.id WHERE(@image=N''all'' OR(@image=N''available'' AND c.photo_available=1) OR(@image=N''missing'' AND c.photo_available=0)) AND(@product_id IS NULL OR p.id=@product_id) AND(@search=N'''' OR CHARINDEX(@search,p.stock_code)>0 OR CHARINDEX(@search,p.name)>0) AND(DATALENGTH(@barcode)=0 OR EXISTS(SELECT 1 FROM dbo.product_barcodes bc WHERE bc.product_id=p.id AND bc.is_active=1 AND bc.barcode=@barcode AND CONVERT(varbinary(max),bc.barcode)=CONVERT(varbinary(max),@barcode))) AND(@stock=N''all'' OR(@stock=N''positive'' AND p.current_stock_qty>0) OR(@stock=N''zero'' AND p.current_stock_qty=0) OR(@stock=N''negative'' AND p.current_stock_qty<0)) AND(@status=N''all'' OR(@status=N''active'' AND p.is_active=1 AND p.is_deleted=0) OR(@status=N''passive'' AND(p.is_active=0 OR p.is_deleted=1))) OPTION(RECOMPILE);
 SELECT m.id,ROW_NUMBER() OVER(ORDER BY CASE WHEN @sort=N''stock-desc'' AND p.current_stock_qty IS NULL THEN 1 ELSE 0 END ASC,CASE WHEN @sort=N''stock-desc'' THEN p.current_stock_qty END DESC,CASE WHEN @sort<>N''code-desc'' THEN c.rank END ASC,CASE WHEN @sort=N''code-desc'' THEN c.rank END DESC,p.id ASC) position INTO #CatalogOrder FROM #StockMatches m JOIN #CatalogClassification c ON c.id=m.id JOIN dbo.products p ON p.id=m.id;
 CREATE UNIQUE CLUSTERED INDEX IX_CatalogOrder ON #CatalogOrder(id);
 CREATE TABLE #StockPage(id bigint NOT NULL PRIMARY KEY,kind nvarchar(30) NOT NULL);
 IF @classification_validation=1 INSERT #StockPage SELECT id,kind FROM #StockScope;
 ELSE INSERT #StockPage SELECT m.id,m.kind FROM #StockMatches m JOIN dbo.products p ON p.id=m.id JOIN #CatalogOrder o ON o.id=m.id ORDER BY o.position OFFSET CONVERT(bigint,@page-1)*@page_size ROWS FETCH NEXT @page_size ROWS ONLY OPTION(RECOMPILE);
 CREATE TABLE #CatalogAliasTargetProducts(product_id bigint NOT NULL PRIMARY KEY);
INSERT #CatalogAliasTargetProducts SELECT h.native_id FROM erp_migration.operation_quarantine_holds h WHERE h.entity=N''product'' AND h.native_id IS NOT NULL
UNION SELECT b.product_id FROM #StockPage s JOIN erp_migration.accepted_price_products b ON b.product_id=s.id;
CREATE TABLE #CatalogAliasTargetSources(source_product_id int NOT NULL PRIMARY KEY);
INSERT #CatalogAliasTargetSources SELECT TRY_CONVERT(int,h.source_id) FROM erp_migration.operation_quarantine_holds h WHERE h.entity=N''product'' AND TRY_CONVERT(int,h.source_id) IS NOT NULL
UNION SELECT TRY_CONVERT(int,b.source_id) FROM #StockPage s JOIN erp_migration.accepted_price_products b ON b.product_id=s.id WHERE TRY_CONVERT(int,b.source_id) IS NOT NULL;
CREATE TABLE #StockAliasPairs(product_id bigint NULL,source_product_id int NULL,pair_count bigint NOT NULL);
INSERT #StockAliasPairs SELECT product_id,source_product_id,COUNT_BIG(*) FROM dbo.product_source_aliases a WHERE EXISTS(SELECT 1 FROM #CatalogAliasTargetProducts t WHERE t.product_id=a.product_id) OR EXISTS(SELECT 1 FROM #CatalogAliasTargetSources t WHERE t.source_product_id=a.source_product_id) GROUP BY product_id,source_product_id;
CREATE UNIQUE CLUSTERED INDEX IX_StockAliasPairs ON #StockAliasPairs(product_id,source_product_id);
CREATE TABLE #StockAliasProductCounts(product_id bigint NULL,alias_count bigint NOT NULL);
INSERT #StockAliasProductCounts SELECT product_id,SUM(pair_count) FROM #StockAliasPairs GROUP BY product_id;
CREATE UNIQUE CLUSTERED INDEX IX_StockAliasProductCounts ON #StockAliasProductCounts(product_id);
CREATE TABLE #StockAliasSourceCounts(source_product_id int NULL,alias_count bigint NOT NULL);
INSERT #StockAliasSourceCounts SELECT source_product_id,SUM(pair_count) FROM #StockAliasPairs GROUP BY source_product_id;
CREATE UNIQUE CLUSTERED INDEX IX_StockAliasSourceCounts ON #StockAliasSourceCounts(source_product_id);
IF DB_NAME()<>N''MELISA_ERP_SIRKET_TEST_20260929_01'' OR CONVERT(nvarchar(128),SERVERPROPERTY(''ServerName''))<>N''Semih\MELISADEV'' THROW 51101,''STOCK_PRODUCT_TARGET_UNAVAILABLE'',1;
IF NOT EXISTS(SELECT 1 FROM erp_migration.runs WHERE run_id=N''VEGA-OPENING-TEST-20261004-06'' AND status=N''COMMITTED'' AND source_hash=''36971dab7296dd171ee0084c185f833b47b96d6a47fe57c8486a2b81d78ef400'' AND plan_hash=''18639c27f276f4263d5e9a6b5037753c78f2c3d341a053055db7cb7b00da2f0a'' AND source_as_of=N''2026-09-30'') THROW 51101,''STOCK_PRODUCT_SOURCE_UNAVAILABLE'',1;
IF (SELECT CONVERT(varchar(64),HASHBYTES(''SHA2_256'',STRING_AGG(CONVERT(nvarchar(max),CONCAT(name,N''|'',CONVERT(varchar(64),HASHBYTES(''SHA2_256'',OBJECT_DEFINITION(object_id)),2),N''|'',is_disabled,N''|'',OBJECTPROPERTY(object_id,''ExecIsFirstInsertTrigger''),N''|'',OBJECTPROPERTY(object_id,''ExecIsFirstUpdateTrigger''),N''|'',OBJECTPROPERTY(object_id,''ExecIsFirstDeleteTrigger''))),N'';'') WITHIN GROUP(ORDER BY name)),2) FROM sys.triggers WHERE name LIKE N''operation[_]quarantine[_]%'' OR name LIKE N''immutable[_]operation[_]%'' OR name LIKE N''immutable[_]accepted[_]%'')<>''9AE41CA1AB25EE165019AD04DBD9A6FB4E5B7190F027E0A07A87FB03D698379E'' THROW 51101,''STOCK_PRODUCT_GUARD_UNAVAILABLE'',1;
IF (SELECT COUNT(*) FROM sys.triggers WHERE name LIKE N''operation[_]quarantine[_]%'' AND is_disabled=0 AND OBJECTPROPERTY(object_id,''ExecIsFirstInsertTrigger'')=1 AND OBJECTPROPERTY(object_id,''ExecIsFirstUpdateTrigger'')=1 AND OBJECTPROPERTY(object_id,''ExecIsFirstDeleteTrigger'')=1)<>37 THROW 51101,''STOCK_PRODUCT_QUARANTINE_UNAVAILABLE'',1;
