 OR(s.kind=N''quarantined-source'' AND(i.stage_payload_hash IS NOT NULL OR i.stage_sql_hash IS NOT NULL OR NOT(CONVERT(varbinary(max),i.source_key)=CONVERT(varbinary(max),N''VEGA_CAPTURE_20260930_01/F0102/TBLSTOKLAR/''+h.source_id))))) THROW 51102,''WORK_CATALOG_BINDING_DRIFT'',1;
