ntPriceGuardHash,CONVERT(char(64),HASHBYTES(''SHA2_256'',OBJECT_DEFINITION(OBJECT_ID(N''dbo.c09_guard_product_price_versions''))),2) c09PriceVersionGuardHash,CONVERT(char(64),HASHBYTES(''SHA2_256'',OBJECT_DEFINITION(OBJECT_ID(N''dbo.c09_guard_product_price_requests''))),2) c09PriceJournalGuardHash,CONVERT(char(64),HASHBYTES(''SHA2_256'',OBJECT_DEFINITION(OBJECT_ID(N''dbo.c09_immutable_test_product_price_manifest''))),2) c09PriceManifestGuardHash,CONVERT(char(64),HASHBYTES(''SHA2_256'',OBJECT_DEFINITION(OBJECT_ID(N''dbo.c09_immutable_test_product_price_scope''))),2) c09PriceScopeGuardHash,CONVERT(char(64),HASHBYTES(''SHA2_256'',OBJECT_DEFINITION(OBJECT_ID(N''dbo.c09_immutable_test_product_price_units''))),2) c09PriceUnitGuardHash,(SELECT CONVERT(varchar(64),HASHBYTES(''SHA2_256'',STRING_AGG(CONVERT(nvarchar(max),CONCAT(name,N''|'',CONVERT(varchar(64),HASHBYTES(''SHA2_256'',OBJECT_DEFINITION(object_id)),2),N''|'',is_disabled,N''|'',OBJECTPROPERTY(object_id,''ExecIsFirstInsertTrigger''),N''|'',OBJECTPROPERTY(object_id,''ExecIsFirstUpdateTrigger''),N''|'',OBJECTPROPERTY(object_id,''ExecIsFirstDeleteTrigger''))),N'';'') WITHIN GROUP(ORDER BY name)),2) FROM sys.triggers WHERE name LIKE N''operation[_]quarantine[_]%'' OR name LIKE N''immutable[_]operation[_]%'' OR name LIKE N''immutable[_]accepted[_]%'') preservedGuardHash,CONVERT(char(64),HASHBYTES(''SHA2_256'',OBJECT_DEFINITION(OBJECT_ID(N''dbo.usp_read_stock_products''))),2) stockReaderDefinitionHash;RETURN;

