 IF @sales=1 BEGIN
SELECT n.* INTO #CatalogNativePagePrices FROM dbo.product_prices n INNER JOIN #StockPage s ON s.id=n.product_id OPTION(RECOMPILE);
CREATE UNIQUE CLUSTERED INDEX IX_CatalogNativePagePrices ON #CatalogNativePagePrices(id);
IF EXISTS(SELECT 1 FROM #StockPage s JOIN erp_migration.accepted_price_values v ON v.product_id=s.id
LEFT JOIN #CatalogNativePagePrices n ON n.id=v.price_id
LEFT JOIN erp_migration.records r ON r.run_id=N''VEGA-OPENING-TEST-20261004-06'' AND r.entity=N''prices'' AND r.source_key=v.price_source_key
WHERE CONVERT(varbinary(max),CONVERT(nvarchar(max),v.price_type))=CONVERT(varbinary(max),N''sale'') AND (
n.id IS NULL OR r.source_key IS NULL OR n.product_id<>v.product_id
OR NOT(CONVERT(varbinary(max),CONVERT(nvarchar(max),n.price_type))=CONVERT(varbinary(max),CONVERT(nvarchar(max),v.price_type)) AND CONVERT(varbinary(max),CONVERT(nvarchar(max),n.currency_code))=CONVERT(varbinary(max),CONVERT(nvarchar(max),v.currency_code)))
OR n.price_tier<>v.price_tier OR EXISTS(SELECT n.source_unit_id,n.price EXCEPT SELECT v.source_unit_id,v.price_exact)
OR v.native_row_hash IS NULL OR CONVERT(char(64),HASHBYTES(''SHA2_256'',(SELECT n.* FOR JSON PATH,WITHOUT_ARRAY_WRAPPER,INCLUDE_NULL_VALUES)),2)<>v.native_row_hash
OR r.payload_hash IS NULL OR r.payload_json IS NULL OR r.payload_hash<>v.stage_payload_hash OR CONVERT(char(64),HASHBYTES(''SHA2_256'',r.payload_json),2)<>v.stage_sql_hash
OR v.binding_hash IS NULL OR v.binding_hash<>CONVERT(char(64),HASHBYTES(''SHA2_256'',(SELECT v.price_id,v.product_id,v.product_source_key,v.price_source_key,v.source_unit_id,v.price_type,v.price_tier,v.currency_code,v.price_exact,v.is_main_unit,v.stage_payload_hash,v.stage_sql_hash,v.native_row_hash FOR JSON PATH,WITHOUT_ARRAY_WRAPPER,INCLUDE_NULL_VALUES)),2)
OR(SELECT COUNT(*) FROM #CatalogNativePagePrices z WHERE z.product_id=v.product_id AND CONVERT(varbinary(max),CONVERT(nvarchar(max),z.price_type))=CONVERT(varbinary(max),CONVERT(nvarchar(max),v.price_type)) AND CONVERT(varbinary(max),CONVERT(nvarchar(max),z.currency_code))=CONVERT(varbinary(max),CONVERT(nvarchar(max),v.currency_code)) AND z.price_tier=v.price_tier AND NOT EXISTS(SELECT z.source_unit_id EXCEPT SELECT v.source_unit_id))<>1)) THROW 51102,''WORK_CATALOG_BINDING_DRIFT'',1;
END;
 SELECT N''{"brands":[],"productTypes":[]}'' filtersJson,CONVERT(varchar(20),@actor_id) actorId,CONVERT(bit,1) canView,@sales canViewSalesPrices,(SELECT COUNT(*) FROM #StockMatches) total,(SELECT COUNT(*) FROM #StockScope WHERE kind=N''accepted-opening'') acceptedCount,(SELECT COUNT(*) FROM #StockScope WHERE kind=N''synthetic-test'') syntheticCount,(SELECT COUNT(*) FROM #StockScope WHERE kind=N''quarantined-source'') quarantinedCount,@page page,@page_size [limit],@read_at readAt,CONVERT(char(64),HASHBYTES(''SHA2_256'',OBJECT_DEFINITION(@@PROCID)),2) readerDefinitionHash,CONVERT(char(64),HASHBYTES(''SHA2_256'',OBJECT_DEFINITION(OBJECT_ID(N''dbo.usp_get_accepted_opening_prices''))),2) openingDetailHash,CONVERT(char(64),HASHBYTES(''SHA2_256'',OBJECT_DEFINITION(OBJECT_ID(N''dbo.usp_list_accepted_opening_products''))),2) openingListHash,CONVERT(char(64),HASHBYTES(''SHA2_256'',OBJECT_DEFINITION(OBJECT_ID(N''erp_migration.immutable_accepted_price_manifest''))),2) acceptedManifestGuardHash,CONVERT(char(64),HASHBYTES(''SHA2_256'',OBJECT_DEFINITION(OBJECT_ID(N''erp_migration.immutable_accepted_price_products''))),2) acceptedProductsGuardHash,CONVERT(char(64),HASHBYTES(''SHA2_256'',OBJECT_DEFINITION(OBJECT_ID(N''erp_migration.immutable_accepted_price_values''))),2) acceptedPricesGuardHash,CONVERT(char(64),HASHBYTES(''SHA2_256'',OBJECT_DEFINITION(OBJECT_ID(N''erp_migration.immutable_operation_quarantine_manifest''))),2) holdManifestGuardHash,CONVERT(char(64),HASHBYTES(''SHA2_256'',OBJECT_DEFINITION(OBJECT_ID(N''erp_migration.immutable_operation_quarantine_holds''))),2) holdRowsGuardHash,CONVERT(char(64),HASHBYTES(''SHA2_256'',OBJECT_DEFINITION(OBJECT_ID(N''dbo.usp_read_customer_cards''))),2) customerReaderHash,CONVERT(char(64),HASHBYTES(''SHA2_256'',OBJECT_DEFINITION(OBJECT_ID(N''dbo.usp_read_supplier_cards''))),2) supplierReaderHash,CONVERT(char(64),HASHBYTES(''SHA2_256'',OBJECT_DEFINITION(OBJECT_ID(N''dbo.usp_get_test_product_prices''))),2) c09PriceGetterHash,CONVERT(char(64),HASHBYTES(''SHA2_256'',OBJECT_DEFINITION(OBJECT_ID(N''dbo.usp_set_test_product_price''))),2) c09PriceSetterHash,CONVERT(char(64),HASHBYTES(''SHA2_256'',OBJECT_DEFINITION(OBJECT_ID(N''dbo.c09_guard_native_product_prices''))),2) c09NativePriceGuardHash,CONVERT(char(64),HASHBYTES(''SHA2_256'',OBJECT_DEFINITION(OBJECT_ID(N''dbo.c09_guard_product_price_current''))),2) c09CurrentPriceGuardHash,CONVERT(char(64),HASHBYTES(''SHA2_256'',OBJECT_DEFINITION(OBJECT_ID(N''dbo.c09_guard_product_price_versions''))),2) c09PriceVersionGuardHash,CONVERT(char(64),HASHBYTES(''SHA2_256'',OBJECT_DEFINITION(OBJECT_ID(N''dbo.c09_guard_product_price_requests''))),2) c09PriceJournalGuardHash,CONVERT(char(64),HASHBYTES(''SHA2_256'',OBJECT_DEFINITION(OBJECT_ID(N''dbo.c09_immutable_test_product_price_manifest''))),2) c09PriceManifestGuardHash,CONVERT(char(64),HASHBYTES(''SHA2_256'',OBJECT_DEFINITION(OBJECT_ID(N''dbo.c09_immutable_test_product_price_scope''))),2) c09PriceScopeGuardHash,CONVERT(char(64),HASHBYTES(''SHA2_256'',OBJECT_DEFINITION(OBJECT_ID(N''dbo.c09_immutable_test_product_price_units''))),2) c09PriceUnitGuardHash,(SELECT CONVERT(varchar(64),HASHBYTES(''SHA2_256'',STRING_AGG(CONVERT(nvarchar(max),CONCAT(name,N''|'',CONVERT(varchar(64),HASHBYTES(''SHA2_256'',OBJECT_DEFINITION(object_id)),2),N''|'',is_disabled,N''|'',OBJECTPROPERTY(object_id,''ExecIsFirstInsertTrigger''),N''|'',OBJECTPROPERTY(object_id,''ExecIsFirstUpdateTrigger''),N''|'',OBJECTPROPERTY(object_id,''ExecIsFirstDeleteTrigger''))),N'';'') WITHIN GROUP(ORDER BY name)),2) FROM sys.triggers WHERE name LIKE N''operation[_]quarantine[_]%'' OR name LIKE N''immutable[_]operation[_]%'' OR name LIKE N''immutable[_]accepted[_]%'') preservedGuardHash,CONVERT(char(64),HASHBYTES(''SHA2_256'',OBJECT_DEFINITION(OBJECT_ID(N''dbo.usp_read_stock_products''))),2) stockReaderDefinitionHash,
 COALESCE(N''[''+(SELECT STRING_AGG(CONVERT(nvarchar(max),j.row_json),N'','') WITHIN GROUP(ORDER BY o.position) FROM #StockPage s JOIN dbo.products p ON p.id=s.id JOIN #CatalogOrder o ON o.id=s.id JOIN #CatalogClassification c ON c.id=s.id LEFT JOIN erp_migration.accepted_price_products b ON b.product_id=p.id LEFT JOIN erp_migration.operation_quarantine_holds ph ON ph.entity=N''product'' AND ph.native_id=p.id LEFT JOIN erp_migration.records r ON r.run_id=N''VEGA-OPENING-TEST-20261004-06'' AND r.entity=N''products'' AND r.source_key=b.product_source_key CROSS APPLY(SELECT(SELECT CONVERT(varchar(20),p.id) id,p.stock_code stockCode,p.name productName,c.display_code displayCode,JSON_QUERY((SELECT c.brand brand,c.product_type productType,c.source_name sourceName,c.verified verified FOR JSON PATH,WITHOUT_ARRAY_WRAPPER,INCLUDE_NULL_VALUES)) classification,CONVERT(bit,CASE WHEN p.is_active=1 AND p.is_deleted=0 THEN 1 ELSE 0 END) isActive,CONVERT(varchar(100),CAST(p.current_stock_qty AS decimal(28,8))) stockQuantityExact,
 JSON_QUERY((SELECT CASE WHEN s.kind=N''synthetic-test'' THEN p.unit WHEN b.product_id IS NOT NULL AND JSON_VALUE(JSON_VALUE(r.payload_json,''$.source_payload_json''),''$.unit'') IS NOT NULL THEN b.unit ELSE NULL END label,CASE WHEN p.id=301986 THEN(SELECT TOP(1) CONVERT(varchar(20),u.id) FROM dbo.test_product_price_units u ORDER BY u.id) WHEN TRY_CONVERT(bigint,JSON_VALUE(JSON_VALUE(r.payload_json,''$.source_payload_json''),''$.mainUnitSourceId''))>0 THEN CONVERT(varchar(20),b.main_unit_source_id) ELSE NULL END sourceId,CASE WHEN (b.product_id IS NOT NULL AND b.unit=N''ADET'' AND JSON_VALUE(JSON_VALUE(r.payload_json,''$.source_payload_json''),''$.unitStatus'')=N''VERIFIED_ADET_FACTOR_1'' AND TRY_CONVERT(decimal(28,8),JSON_VALUE(JSON_VALUE(r.payload_json,''$.source_payload_json''),''$.unitFactor''))=1) OR(p.id=301986 AND EXISTS(SELECT 1 FROM dbo.test_product_price_units u WHERE u.label=N''ADET'' AND u.factor=1)) THEN CONVERT(varchar(100),CAST(1 AS decimal(28,8))) ELSE NULL END factorExact8,CONVERT(bit,CASE WHEN (b.product_id IS NOT NULL AND b.unit=N''ADET'' AND JSON_VALUE(JSON_VALUE(r.payload_json,''$.source_payload_json''),''$.unitStatus'')=N''VERIFIED_ADET_FACTOR_1'' AND TRY_CONVERT(decimal(28,8),JSON_VALUE(JSON_VALUE(r.payload_json,''$.source_payload_json''),''$.unitFactor''))=1) OR(p.id=301986 AND EXISTS(SELECT 1 FROM dbo.test_product_price_units u WHERE u.label=N''ADET'' AND u.factor=1)) THEN 1 ELSE 0 END) verified FOR JSON PATH,WITHOUT_ARRAY_WRAPPER,INCLUDE_NULL_VALUES)) unit,
 JSON_QUERY(COALESCE((SELECT CONVERT(varchar(20),bc.id) id,bc.barcode value,bc.is_primary isPrimary,CAST(NULL AS nvarchar(250)) sourceKey FROM dbo.product_barcodes bc WHERE bc.product_id=p.id AND bc.is_active=1 ORDER BY bc.is_primary DESC,bc.id FOR JSON PATH,INCLUDE_NULL_VALUES),N''[]'')) barcodes,
 CAST(NULL AS nvarchar(max)) imageUrl,
 JSON_QUERY(N''{"status":"missing","url":null,"sourceKey":null,"verified":false}'') photo,
 JSON_QUERY(COALESCE((SELECT CONVERT(varchar(20),v.price_id) id,v.price_type type,CONVERT(varchar(20),v.source_unit_id) unitSourceId,v.price_tier tier,v.currency_code currency,CONVERT(varchar(100),v.price_exact) priceExact,v.is_main_unit isMainUnit,v.price_source_key sourceKey FROM erp_migration.accepted_price_values v WHERE @sales=1 AND s.kind=N''accepted-opening'' AND v.product_id=p.id AND CONVERT(varbinary(max),CONVERT(nvarchar(max),v.price_type))=CONVERT(varbinary(max),N''sale'') ORDER BY v.source_unit_id,v.price_tier,v.currency_code,v.price_id FOR JSON PATH,INCLUDE_NULL_VALUES),N''[]'')) salePrices,
 JSON_QUERY((SELECT s.kind kind,COALESCE(b.product_source_key,ph.source_key) sourceKey,CASE WHEN s.kind<>N''synthetic-test'' THEN N''VEGA-OPENING-TEST-20261004-06'' ELSE NULL END runId,CASE WHEN s.kind<>N''synthetic-test'' THEN N''2026-09-30'' ELSE NULL END sourceAsOf,CONVERT(bit,1) verified FOR JSON PATH,WITHOUT_ARRAY_WRAPPER,INCLUDE_NULL_VALUES)) provenance,
 JSON_QUERY((SELECT CONVERT(bit,CASE WHEN EXISTS(SELECT 1 FROM erp_migration.operation_quarantine_holds h WHERE h.entity=N''product'' AND(h.native_id=p.id OR CONVERT(varbinary(max),h.native_source_key)=CONVERT(varbinary(max),p.source_record_key) OR EXISTS(SELECT 1 FROM #StockAliasPairs a WHERE a.product_id=p.id AND a.source_product_id=TRY_CONVERT(int,h.source_id)))) THEN 1 ELSE 0 END) blocked,JSON_QUERY(COALESCE((SELECT TOP(1) h.reasons_json FROM erp_migration.operation_quarantine_holds h WHERE h.entity=N''product'' AND h.native_id=p.id),N''[]'')) reasons FOR JSON PATH,WITHOUT_ARRAY_WRAPPER)) hold
 FOR JSON PATH,WITHOUT_ARRAY_WRAPPER,INCLUDE_NULL_VALUES) row_json) j)+N'']'',N''[]'') rowsJson;
 END;';
SET @catalog_definition=REPLACE(@catalog_definition,NCHAR(13)+NCHAR(10),NCHAR(10));
IF OBJECT_ID(N'dbo.usp_read_work_catalog') IS NOT NULL BEGIN
 IF OBJECT_ID(N'dbo.usp_read_work_catalog',N'P') IS NULL THROW 51102,'WORK_CATALOG_DEFINITION_DRIFT',1;
 DECLARE @prior_definition_hash char(64)=CONVERT(char(64),HASHBYTES('SHA2_256',OBJECT_DEFINITION(OBJECT_ID(N'dbo.usp_read_work_catalog'))),2);
 IF DATABASE_PRINCIPAL_ID(N'melisa_sirket_test_20260929_01') IS NULL OR NOT EXISTS(SELECT 1 FROM sys.database_permissions WHERE class=1 AND major_id=OBJECT_ID(N'dbo.usp_read_work_catalog') AND minor_id=0 AND grantee_principal_id=DATABASE_PRINCIPAL_ID(N'melisa_sirket_test_20260929_01') AND permission_name=N'EXECUTE' AND state=N'G') THROW 51102,'WORK_CATALOG_EXECUTE_DRIFT',1;
